"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { ArrowUpRight } from "./icons";

// Chart: generated by UIX from the design system. Same variants and sizes as the Figma component.

export interface ChartDatum {
  label: string;
  value: number;
}

// Plot area of the bar and line charts, in SVG units.
const PLOT = { width: 440, height: 200, top: 4, base: 172 };
const RING = 2 * Math.PI * 76.5;
const SLICE_STROKES = ["stroke-brand","stroke-secondary","stroke-success","stroke-warning"];
const SLICE_DOTS = ["bg-brand","bg-secondary","bg-success","bg-warning"];

const chartVariants = cva(
  "flex w-full max-w-[480px] flex-col gap-4 p-5 bg-surface text-fg-primary border border-line-default rounded-xl",
  {
    variants: {
      type: {
        bar: "",
        line: "",
        donut: "",
      },
    },
    defaultVariants: {
      type: "bar",
    },
  },
);

export interface ChartProps
  extends Omit<React.HTMLAttributes<HTMLElement>, "title">,
    VariantProps<typeof chartVariants> {
  data: ChartDatum[];
  title?: React.ReactNode;
  /** Headline figure, for example $48.2k. */
  value?: React.ReactNode;
  /** Change next to the value, for example 12.5%. */
  delta?: React.ReactNode;
  /** Bar chart: index of the highlighted bar (defaults to the tallest). */
  highlight?: number;
}

const Chart = React.forwardRef<HTMLElement, ChartProps>(
  ({ className, type, data, title, value, delta, highlight, ...props }, ref) => {
    const kind = type ?? "bar";
    const max = Math.max(...data.map((item) => item.value), 1);
    const total = data.reduce((sum, item) => sum + item.value, 0) || 1;
    const pitch = PLOT.width / Math.max(data.length, 1);
    const y = (amount: number) => PLOT.base - (amount / max) * (PLOT.base - PLOT.top);
    const peak = highlight ?? data.reduce((best, item, index) => (item.value > data[best].value ? index : best), 0);
    const points = data.map((item, index) => [pitch * (index + 0.5), y(item.value)]);
    const line = points.map((point, index) => (index ? "L " : "M ") + point[0] + " " + point[1]).join(" ");
    let used = 0;
    return (
      <figure data-slot="chart" data-kind="surface" ref={ref} className={cn(chartVariants({ type }), className)} {...props}>
        <figcaption className="flex flex-col gap-1">
          {title ? <span className="text-label-large text-fg-secondary">{title}</span> : null}
          <span className="flex items-center gap-2">
            {value ? <span className="text-heading-4 text-fg-primary">{value}</span> : null}
            {delta ? <span className="inline-flex items-center rounded-full gap-0-5 px-1-5 py-0-5 bg-success-subtle text-label-small text-fg-success [&_svg]:size-3"><ArrowUpRight aria-hidden />{delta}</span> : null}
          </span>
        </figcaption>
        {kind === "donut" ? (
          <div className="flex items-center gap-6">
            <svg viewBox="0 0 200 200" role="img" aria-label={typeof title === "string" ? title : "Chart"} className="size-[180px] shrink-0 -rotate-90">
              {data.map((item, index) => {
                const length = (item.value / total) * RING;
                const start = used;
                used += length;
                return <circle key={item.label} cx="100" cy="100" r="76.5" fill="none" strokeWidth="27" strokeDasharray={Math.max(length - 2, 0) + " " + RING} strokeDashoffset={-start} className={SLICE_STROKES[index % SLICE_STROKES.length]} />;
              })}
            </svg>
            <ul className="flex flex-1 flex-col gap-2 text-body-small text-fg-secondary">
              {data.map((item, index) => (
                <li key={item.label} className="flex items-center gap-2">
                  <span aria-hidden className={cn("shrink-0 rounded-full size-2", SLICE_DOTS[index % SLICE_DOTS.length])} />
                  <span className="flex-1">{item.label}</span>
                  <span className="text-fg-primary">{Math.round((item.value / total) * 100)}%</span>
                </li>
              ))}
            </ul>
          </div>
        ) : (
          <svg viewBox={"0 0 " + PLOT.width + " " + PLOT.height} role="img" aria-label={typeof title === "string" ? title : "Chart"} className="h-auto w-full">
            {[PLOT.top, 60, 116, PLOT.base].map((position) => (
              <line key={position} x1="0" x2={PLOT.width} y1={position} y2={position} className="stroke-line-subtle" />
            ))}
            {kind === "bar" ? data.map((item, index) => {
              const height = (item.value / max) * (PLOT.base - PLOT.top);
              const width = Math.min(20, pitch * 0.6);
              return <rect key={item.label} x={index * pitch + (pitch - width) / 2} y={PLOT.base - height} width={width} height={height} rx="3" className={index === peak ? "fill-brand" : "fill-brand-subtle"} />;
            }) : (
              <>
                <path d={line + " L " + (points.length ? points[points.length - 1][0] : 0) + " " + PLOT.base + " L " + (points.length ? points[0][0] : 0) + " " + PLOT.base + " Z"} className="fill-brand/12" />
                <path d={line} fill="none" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="stroke-brand" />
                {points.map((point, index) => (
                  <circle key={data[index].label} cx={point[0]} cy={point[1]} r={index === points.length - 1 ? 5 : 4} strokeWidth="2" className={index === points.length - 1 ? "fill-brand stroke-brand" : "fill-surface stroke-brand"} />
                ))}
              </>
            )}
            {data.map((item, index) => (
              <text key={item.label} x={pitch * (index + 0.5)} y="194" textAnchor="middle" className="fill-fg-tertiary text-body-xs">
                {item.label}
              </text>
            ))}
          </svg>
        )}
        <ul className="sr-only">
          {data.map((item) => (
            <li key={item.label}>{item.label + ": " + item.value}</li>
          ))}
        </ul>
      </figure>
    );
  },
);
Chart.displayName = "Chart";

export { Chart, chartVariants };
